#!/usr/bin/env python3
import rclpy
from rclpy.node import Node

class HelloRobot(Node):
    def __init__(self):
        super().__init__('hello_robot')
        self.create_timer(1.0, self.tick)
        self.count = 0

    def tick(self):
        self.count += 1
        self.get_logger().info(f'ROSOrin Pro 노드 실행 중... {self.count}')

def main():
    rclpy.init()
    rclpy.spin(HelloRobot())

if __name__ == '__main__':
    main()
